package com.vms.vendorcontractmanagement.entity; import jakarta.persistence.*; import lombok.*; import java.math.*; import java.time.*;
@Entity @Table(name="contracts") @Getter @Setter @NoArgsConstructor public class Contract { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="contract_id") Long id; @Column(unique=true) String contractNumber; @ManyToOne(optional=false) @JoinColumn(name="vendor_id") Vendor vendor; LocalDate startDate,endDate; BigDecimal contractValue; String paymentFrequency,status="DRAFT",renewalStatus="PENDING"; LocalDateTime createdAt; @PrePersist void created(){createdAt=LocalDateTime.now();} }
